protected override void append_name_for_namespace_type(StringBuilder sb, DefType type)
{
    if (TryAppendKeyword(sb, type))
    {
        return;
    }

    string ns = type.GetNamespace();
    if (ns.Length > 0)
    {
        sb.Append(ns);
        sb.Append('.');
    }
    AppendTypeName(sb, type);
}
